import boto3, io, zipfile
import cfnresponse
def handler(e, c):
    p = e['ResourceProperties']; s3 = boto3.client('s3')
    try:
        if e['RequestType'] == 'Delete':
            s3.delete_object(Bucket=p['Bucket'], Key=p['Key'])
        else:
            buf = io.BytesIO(); z = zipfile.ZipFile(buf, 'w'); z.writestr('app.py', p['Body']); z.close()
            s3.put_object(Bucket=p['Bucket'], Key=p['Key'], Body=buf.getvalue())
        cfnresponse.send(e, c, cfnresponse.SUCCESS, {}, p['Key'])
    except Exception as ex:
        cfnresponse.send(e, c, cfnresponse.FAILED, {'err': str(ex)}, p['Key'])

